:root{--bg:#07111e;--card:#0c1a2b;--card2:#102238;--line:#1d3250;--acc:#7c9eff;--text:#e6edf8;--dim:#c7d6ec;--faint:#9cb0cf;--sb:280px}
*{box-sizing:border-box}html{scroll-behavior:smooth;overflow-x:hidden}
body{margin:0;background:var(--bg);color:var(--text);font:16px/1.85 "Noto Sans JP","Hiragino Kaku Gothic ProN","Yu Gothic",Meiryo,sans-serif;overflow-x:hidden}
#sidebar{position:fixed;left:0;top:0;bottom:0;width:var(--sb);background:#050d17;border-right:1px solid var(--line);overflow-y:auto;padding:20px 14px;z-index:20}
.brand{font-weight:800;color:var(--acc);margin-bottom:14px;font-size:15px}
#sidebar ul{list-style:none;margin:0;padding:0}#sidebar a{display:block;padding:7px 10px;border-radius:8px;color:var(--faint);text-decoration:none;font-size:13.5px;line-height:1.5;border-left:3px solid transparent}
#sidebar a:hover{color:var(--text);background:var(--card)}#sidebar a.active{color:#fff;background:var(--card2);border-left-color:var(--acc)}
.main{margin-left:var(--sb);padding:40px 48px 80px}
.hero{position:relative;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:32px 36px;margin-bottom:36px;overflow:hidden}
.hero::before{content:"";position:absolute;top:-80px;right:-80px;width:320px;height:320px;background:radial-gradient(circle,rgba(124,158,255,.25),transparent 70%)}
.badge{display:inline-block;padding:4px 14px;border-radius:999px;background:rgba(124,158,255,.15);color:var(--acc);font-size:12.5px;font-weight:700;border:1px solid rgba(124,158,255,.4)}
.hero-title{font-size:28px;font-weight:800;color:#fff;margin:14px 0 18px;line-height:1.4}
.metas{display:flex;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:14px}.m{padding:0 22px;border-right:1px solid var(--line);flex:1 1 220px}.m:first-child{padding-left:0}.m:last-child{border-right:0}
.m span{display:block;font-size:11px;letter-spacing:.08em;color:var(--faint);text-transform:uppercase}.m b{font-size:14px;font-weight:500;color:var(--dim)}
h2{font-size:23px;margin:56px 0 18px;padding-bottom:10px;border-bottom:2px solid var(--line);color:#fff;scroll-margin-top:20px}
h3{font-size:18px;margin:34px 0 12px;color:var(--acc)}p,li{color:var(--dim)}strong{color:#fff}a{color:var(--acc);word-break:break-all}
code:not(pre code){background:var(--card2);padding:2px 6px;border-radius:5px;font-family:"JetBrains Mono",monospace;font-size:.9em}
.table-scroll{overflow-x:auto;margin:16px 0;border:1px solid var(--line);border-radius:10px}
table{border-collapse:collapse;width:100%;font-size:14.5px}th{background:var(--card2);color:#fff;text-align:left}th,td{padding:10px 14px;border-bottom:1px solid var(--line);vertical-align:top}tr:last-child td{border-bottom:0}tbody tr:nth-child(even){background:rgba(255,255,255,.02)}
blockquote.callout{margin:18px 0;padding:12px 18px;border-left:4px solid var(--acc);background:var(--card);border-radius:0 10px 10px 0}blockquote.callout p{margin:6px 0}
.mermaid-diagram{display:block;overflow-x:auto;border:1px solid var(--line);background:var(--card);border-radius:12px;padding:20px;margin:20px 0}
.mermaid-diagram svg{display:block;margin-left:auto;margin-right:auto;max-width:none;flex-shrink:0}
.mermaid-diagram p{color:inherit;margin:0}
details{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 18px;margin:12px 0}summary{cursor:pointer;font-weight:700;color:#fff}details[open] summary{margin-bottom:8px}
ol,ul{padding-left:1.4em}.page-footer{margin-top:60px;padding-top:18px;border-top:1px solid var(--line);color:var(--faint);font-size:13px}
#navtoggle{display:none;position:fixed;top:12px;left:12px;z-index:30;background:var(--card2);color:#fff;border:1px solid var(--line);border-radius:8px;padding:6px 12px;font-size:18px}
@media(max-width:900px){#sidebar{transform:translateX(-100%);transition:transform .2s}#sidebar.open{transform:none}#navtoggle{display:block}.main{margin-left:0;padding:60px 18px 60px}.hero{padding:22px}.m{border-right:0;border-bottom:1px solid var(--line);padding:8px 0;flex-basis:100%}}
